'use strict';

function createDisclosureModel(items) {
  if (!Array.isArray(items)) throw new TypeError('items must be an array');
  const seen = new Set();
  const state = items.map(item => {
    if (!item || typeof item !== 'object' || Array.isArray(item) || typeof item.id !== 'string' || item.id.length === 0 || typeof item.summary !== 'string' || item.summary.length === 0 || typeof item.details !== 'string' || item.details.length === 0) throw new TypeError('invalid item');
    if (seen.has(item.id)) throw new RangeError('duplicate id');
    seen.add(item.id);
    return { id: item.id, summary: item.summary, details: item.details, expanded: true };
  });
  return {
    snapshot() {
      return state.map(item => ({ id: item.id, summary: item.summary, details: item.details, expanded: item.expanded }));
    },
    toggle(id) {
      if (typeof id !== 'string' || id.length === 0) throw new TypeError('invalid id');
      const item = state.find(entry => entry.id === id);
      if (!item) return null;
      item.expanded = !item.expanded;
      return item.expanded;
    }
  };
}

module.exports = { createDisclosureModel };

