'use strict';
const assert = require('node:assert');
const api = require('./solution');
assert.deepStrictEqual(Object.keys(api).sort(), ['createDisclosureModel']);
const { createDisclosureModel } = api;

assert.throws(() => createDisclosureModel(), TypeError);
assert.throws(() => createDisclosureModel(null), TypeError);
assert.throws(() => createDisclosureModel([{ id: 'a', summary: 'A', details: 'D' }, { id: 'a', summary: 'B', details: 'E' }]), RangeError);
for (const bad of [
  null,
  [],
  { id: '', summary: 'S', details: 'D' },
  { id: 'a', summary: '', details: 'D' },
  { id: 'a', summary: 'S', details: '' },
  { id: 1, summary: 'S', details: 'D' }
]) assert.throws(() => createDisclosureModel([bad]), TypeError);

const empty = createDisclosureModel([]);
assert.deepStrictEqual(empty.snapshot(), []);
assert.strictEqual(empty.toggle('missing'), null);

const items = [
  { id: 'one', summary: 'First', details: 'First details' },
  { id: 'two', summary: 'Second', details: 'Second details' }
];
const original = JSON.parse(JSON.stringify(items));
const model = createDisclosureModel(items);
assert.deepStrictEqual(items, original);
items[0].summary = 'changed externally';
assert.deepStrictEqual(model.snapshot(), [
  { ...original[0], expanded: false },
  { ...original[1], expanded: false }
]);
assert.strictEqual(model.toggle('one'), true);
assert.deepStrictEqual(model.snapshot(), [
  { ...original[0], expanded: true },
  { ...original[1], expanded: false }
]);
assert.strictEqual(model.toggle('missing'), null);
assert.deepStrictEqual(model.snapshot().map(x => x.expanded), [true, false]);
assert.strictEqual(model.toggle('one'), false);
assert.strictEqual(model.toggle('two'), true);

const oldSnapshot = model.snapshot();
const newSnapshot = model.snapshot();
assert.notStrictEqual(oldSnapshot, newSnapshot);
assert.notStrictEqual(oldSnapshot[0], newSnapshot[0]);
oldSnapshot[0].summary = 'corrupt';
oldSnapshot.push({ id: 'x' });
assert.strictEqual(model.toggle('two'), false);
assert.deepStrictEqual(newSnapshot, [
  { ...original[0], expanded: false },
  { ...original[1], expanded: true }
]);
assert.deepStrictEqual(model.snapshot(), [
  { ...original[0], expanded: false },
  { ...original[1], expanded: false }
]);

for (const bad of [undefined, null, '', 1, {}, []]) assert.throws(() => model.toggle(bad), TypeError);

